import os
import re
import unicodedata
import hashlib
import hmac
import secrets
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file, abort
from functools import wraps
import sqlite3
import bcrypt

app = Flask(__name__)
app.config['UPLOAD_DIR'] = '/var/app/uploads'
app.config['SECRET_KEY'] = secrets.token_hex(32)

BLOCKED_PATTERNS = [
    r'\.\.',
    r'\.\./',
    r'/\.\.',
    r'\\',
    r'%2e%2e',
    r'%2f',
    r'%5c',
]

def get_db():
    conn = sqlite3.connect('/var/app/data.db')
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS files (
        id INTEGER PRIMARY KEY,
        owner TEXT NOT NULL,
        filename TEXT NOT NULL,
        storage_name TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing token'}), 401
        token = auth_header[7:]
        parts = token.split(':')
        if len(parts) != 3:
            return jsonify({'error': 'Invalid token format'}), 401
        username, timestamp, signature = parts
        expected = hmac.new(
            app.config['SECRET_KEY'].encode(),
            f"{username}:{timestamp}".encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return jsonify({'error': 'Invalid signature'}), 401
        request.current_user = username
        return f(*args, **kwargs)
    return decorated

def normalize_path_component(filename):
    """Normalize a filename to prevent directory traversal.

    Strategy:
    1. Unicode NFC normalization to canonical form
    2. Strip null bytes
    3. Check against blocked patterns
    4. Resolve to basename only
    """
    # Step 1: Normalize Unicode to NFC form
    normalized = unicodedata.normalize('NFC', filename)

    # Step 2: Remove null bytes
    normalized = normalized.replace('\x00', '')

    # Step 3: Check blocked patterns on the normalized form
    for pattern in BLOCKED_PATTERNS:
        if re.search(pattern, normalized, re.IGNORECASE):
            raise ValueError(f"Blocked pattern detected: {pattern}")

    # Step 4: NFKC normalization for compatibility equivalence
    # This handles cases like fullwidth characters
    normalized = unicodedata.normalize('NFKC', normalized)

    # Step 5: Extract basename
    basename = os.path.basename(normalized)

    if not basename or basename.startswith('.'):
        raise ValueError("Invalid filename")

    return basename

def safe_join_path(base_dir, user_path):
    """Safely join base directory with user-provided path component."""
    try:
        clean_name = normalize_path_component(user_path)
    except ValueError as e:
        return None, str(e)

    full_path = os.path.join(base_dir, clean_name)

    # Verify the resolved path is within base_dir
    real_base = os.path.realpath(base_dir)
    real_full = os.path.realpath(full_path)

    if not real_full.startswith(real_base + os.sep) and real_full != real_base:
        return None, "Path traversal detected"

    return full_path, None

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?',
        (data['username'],)
    ).fetchone()
    db.close()

    if not user or not bcrypt.checkpw(
        data['password'].encode(), user['password_hash'].encode()
    ):
        return jsonify({'error': 'Invalid credentials'}), 401

    timestamp = str(int(__import__('time').time()))
    signature = hmac.new(
        app.config['SECRET_KEY'].encode(),
        f"{data['username']}:{timestamp}".encode(),
        hashlib.sha256
    ).hexdigest()

    token = f"{data['username']}:{timestamp}:{signature}"
    return jsonify({'token': token})

@app.route('/api/files', methods=['GET'])
@authenticate
def list_files():
    db = get_db()
    files = db.execute(
        'SELECT filename, created_at FROM files WHERE owner = ?',
        (request.current_user,)
    ).fetchall()
    db.close()
    return jsonify({'files': [dict(f) for f in files]})

@app.route('/api/files/<path:filename>', methods=['GET'])
@authenticate
def download_file(filename):
    """Download a file. The filename is first decoded, then normalized."""
    # Decode any percent-encoding that Flask didn't handle
    import urllib.parse
    decoded_filename = urllib.parse.unquote(filename)

    # Apply our path normalization
    user_dir = os.path.join(app.config['UPLOAD_DIR'], request.current_user)
    file_path, error = safe_join_path(user_dir, decoded_filename)

    if error:
        return jsonify({'error': error}), 400

    if not os.path.isfile(file_path):
        return jsonify({'error': 'File not found'}), 404

    return send_file(file_path)

@app.route('/api/files/export', methods=['POST'])
@authenticate
def export_files():
    """Export files by name list. Supports bulk download."""
    data = request.get_json()
    if not data or 'filenames' not in data:
        return jsonify({'error': 'Missing filenames'}), 400

    filenames = data['filenames']
    if not isinstance(filenames, list) or len(filenames) > 20:
        return jsonify({'error': 'Invalid filenames list'}), 400

    user_dir = os.path.join(app.config['UPLOAD_DIR'], request.current_user)
    results = []

    for fname in filenames:
        if not isinstance(fname, str):
            continue
        # Normalize using NFKD for search/matching purposes
        search_name = unicodedata.normalize('NFKD', fname)
        # Remove combining characters for fuzzy matching
        search_name = ''.join(
            c for c in search_name 
            if not unicodedata.combining(c)
        )

        # Check if this matches any file in the database
        db = get_db()
        file_record = db.execute(
            'SELECT storage_name FROM files WHERE owner = ? AND filename = ?',
            (request.current_user, search_name)
        ).fetchone()
        db.close()

        if file_record:
            storage_path = os.path.join(user_dir, file_record['storage_name'])
            if os.path.isfile(storage_path):
                with open(storage_path, 'r') as f:
                    results.append({'name': fname, 'content': f.read()})

    return jsonify({'files': results})

@app.route('/api/files/preview', methods=['POST'])
@authenticate  
def preview_file():
    """Preview a file with optional path for nested storage."""
    data = request.get_json()
    if not data or 'path' not in data:
        return jsonify({'error': 'Missing path'}), 400

    raw_path = data['path']
    if not isinstance(raw_path, str) or len(raw_path) > 255:
        return jsonify({'error': 'Invalid path'}), 400

    # Security: normalize and validate the path
    # First pass: NFC normalization and blocked pattern check
    step1 = unicodedata.normalize('NFC', raw_path)
    step1 = step1.replace('\x00', '')

    for pattern in BLOCKED_PATTERNS:
        if re.search(pattern, step1, re.IGNORECASE):
            return jsonify({'error': 'Blocked pattern'}), 403

    # Second pass: NFKC to resolve compatibility characters
    step2 = unicodedata.normalize('NFKC', step1)

    # Build the full path
    user_dir = os.path.join(app.config['UPLOAD_DIR'], request.current_user)
    target = os.path.join(user_dir, step2)

    # Canonicalize and check containment
    real_target = os.path.realpath(target)
    real_base = os.path.realpath(user_dir)

    if not real_target.startswith(real_base + os.sep):
        return jsonify({'error': 'Access denied'}), 403

    if not os.path.isfile(real_target):
        return jsonify({'error': 'Not found'}), 404

    try:
        with open(real_target, 'r') as f:
            content = f.read(4096)
        return jsonify({'preview': content})
    except Exception:
        return jsonify({'error': 'Cannot read file'}), 500

@app.route('/api/admin/files/<path:filepath>', methods=['GET'])
@authenticate
def admin_read_file(filepath):
    """Admin endpoint to read any user's file for moderation."""
    db = get_db()
    user = db.execute(
        'SELECT role FROM users WHERE username = ?',
        (request.current_user,)
    ).fetchone()
    db.close()

    if not user or user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    # Admin can specify paths like "username/filename"
    # Normalize the filepath
    import urllib.parse
    decoded = urllib.parse.unquote(filepath)

    # Security check: blocked patterns
    check_str = unicodedata.normalize('NFC', decoded)
    for pattern in BLOCKED_PATTERNS:
        if re.search(pattern, check_str, re.IGNORECASE):
            return jsonify({'error': 'Blocked'}), 403

    # NFKC normalize after security check
    final_path = unicodedata.normalize('NFKC', decoded)

    full_path = os.path.join(app.config['UPLOAD_DIR'], final_path)
    real_path = os.path.realpath(full_path)
    real_base = os.path.realpath(app.config['UPLOAD_DIR'])

    if not real_path.startswith(real_base + os.sep):
        return jsonify({'error': 'Path traversal blocked'}), 403

    if not os.path.isfile(real_path):
        return jsonify({'error': 'Not found'}), 404

    with open(real_path, 'r') as f:
        return jsonify({'content': f.read()})

